ns.byEnchant={}
for id,patch in pairs(patches) do
 local option=assert(ns.byID[id],"DB2 catalogue mismatch: "..id)
 option.db2Effect=option.effect
 for key,value in pairs(patch) do option[key]=value end
end
ns.bySlot={}
for _,option in ipairs(ns.catalog) do
 ns.byEnchant[option.enchantID]=ns.byEnchant[option.enchantID] or option
 for _,slot in ipairs(option.slots) do
  ns.bySlot[slot]=ns.bySlot[slot] or {}
  table.insert(ns.bySlot[slot],option)
 end
end
